import json
import os
import subprocess
import sys
import tempfile
import unicodedata
import unittest

ROOT_DIR = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
APPLY_CHANGES = os.path.join(ROOT_DIR, "src", "scripts", "apply-changes.py")


def run_script(script, *args):
    return subprocess.run(
        [sys.executable, script, *args],
        capture_output=True,
        text=True,
        timeout=30,
    )


def make_change(**overrides):
    change = {
        "stage": "mechanical",
        "line": 1,
        "type": "typo",
        "level": "word",
        "before": "המחשבה",
        "after": "ההמחשבה",
        "rationale": "doubled letter",
        "meaningRisk": "low",
    }
    change.update(overrides)
    return change


class ApplyChangesTestCase(unittest.TestCase):
    """Shared helper: write a proof-base + changes payload to a temp dir,
    run apply-changes.py against them, and return (result_json, final_text,
    original_text, proc).
    """

    def _run(self, changes_payload, proof_base_text, extra_args=None, output_path=None):
        extra_args = extra_args or []
        with tempfile.TemporaryDirectory() as tmpdir:
            changes_path = os.path.join(tmpdir, "changes.json")
            proof_base_path = os.path.join(tmpdir, "proof_base.md")
            with open(changes_path, "w", encoding="utf-8") as fh:
                json.dump(changes_payload, fh, ensure_ascii=False)
            with open(proof_base_path, "w", encoding="utf-8") as fh:
                fh.write(proof_base_text)

            args = ["--changes", changes_path, "--proof-base", proof_base_path, "--json"]
            out_path = None
            if output_path == "use-output":
                out_path = os.path.join(tmpdir, "out.md")
                args += ["--output", out_path]
            args += extra_args

            proc = run_script(APPLY_CHANGES, *args)
            self.assertEqual(proc.returncode, 0, proc.stderr)
            result = json.loads(proc.stdout)

            final_read_path = out_path if out_path else proof_base_path
            final_text = None
            if os.path.exists(final_read_path):
                with open(final_read_path, "r", encoding="utf-8") as fh:
                    final_text = fh.read()
            with open(proof_base_path, "r", encoding="utf-8") as fh:
                proof_base_after = fh.read()

        return result, final_text, proof_base_after, proc


class TestBottomToTopOrdering(ApplyChangesTestCase):
    def test_two_edits_same_line_both_land_correctly(self):
        # Two edits target disjoint spans on the same line. Applying
        # right-to-left within the line (part of the bottom-to-top
        # discipline) must not let the first edit shift the second's
        # offset, and vice versa.
        changes = [
            make_change(line=1, before="אבג", after="XXX", rationale="first span"),
            make_change(line=1, before="זחט", after="YYY", rationale="second span"),
        ]
        proof_base = "אבג דהו זחט\n"
        result, _, final_text, _ = self._run({"stage": "mechanical", "changes": changes}, proof_base)
        self.assertEqual(final_text, "XXX דהו YYY\n")
        for out in result["changes"]:
            self.assertTrue(out["applied"], out)
            self.assertIsNone(out["skipReason"])

    def test_edits_across_multiple_lines_bottom_to_top(self):
        # An edit on an earlier line that changes line length must not
        # affect resolution of an edit on a later line -- proven by
        # replacing a short token with a much longer one on line 1 while
        # line 2's edit is resolved independently by its own line content.
        changes = [
            make_change(line=1, before="אבג", after="אבגאבגאבגאבג", rationale="lengthen line 1"),
            make_change(line=2, before="טעות", after="תיקון", rationale="fix line 2"),
        ]
        proof_base = "אבג דהו\nשורה עם טעות קטנה\n"
        result, _, final_text, _ = self._run({"stage": "mechanical", "changes": changes}, proof_base)
        self.assertEqual(final_text, "אבגאבגאבגאבג דהו\nשורה עם תיקון קטנה\n")
        for out in result["changes"]:
            self.assertTrue(out["applied"], out)


class TestNfcInsensitivity(ApplyChangesTestCase):
    def test_nfd_before_matches_nfc_source(self):
        raw = "המחשבה"
        nfd_before = unicodedata.normalize("NFD", raw)
        nfd_after = unicodedata.normalize("NFD", "ההמחשבה")
        change = make_change(line=1, before=nfd_before, after=nfd_after, rationale="nfc test")
        proof_base = unicodedata.normalize("NFC", raw) + " המרכזית\n"
        result, _, final_text, _ = self._run({"stage": "mechanical", "changes": [change]}, proof_base)
        out = result["changes"][0]
        self.assertTrue(out["applied"], out)
        self.assertIn("ההמחשבה", unicodedata.normalize("NFC", final_text))


class TestNoMatch(ApplyChangesTestCase):
    def test_no_match_is_recorded_skipped_not_dropped_and_file_untouched(self):
        change = make_change(
            line=1,
            before="טקסט שאינו קיים בשורה",
            after="טקסט מתוקן",
            rationale="placeholder edit",
        )
        proof_base = "שורה שונה לגמרי שאינה מכילה את הטקסט המקורי.\n"
        result, _, final_text, _ = self._run({"stage": "mechanical", "changes": [change]}, proof_base)
        self.assertEqual(len(result["changes"]), 1)
        out = result["changes"][0]
        self.assertFalse(out["applied"])
        self.assertEqual(out["skipReason"], "no-match")
        self.assertEqual(final_text, proof_base)


class TestAmbiguousMatch(ApplyChangesTestCase):
    def test_ambiguous_before_is_not_applied_to_wrong_instance(self):
        change = make_change(line=1, before="אבג", after="X", rationale="ambiguous")
        proof_base = "אבג אבג\n"
        result, _, final_text, _ = self._run({"stage": "mechanical", "changes": [change]}, proof_base)
        out = result["changes"][0]
        self.assertFalse(out["applied"])
        self.assertEqual(out["skipReason"], "ambiguous-match")
        self.assertEqual(final_text, proof_base)


    def test_ambiguous_match_is_never_resolved_via_neighbouring_line(self):
        # Same-line duplicate, but with neighbour lines above and below that
        # each contain a *unique* occurrence of `before` too. A widening
        # implementation would be tempted to "resolve" the ambiguity by
        # picking one of those neighbours; this must never happen -- the
        # change must come back skipReason="ambiguous-match" and the file
        # must be left completely untouched (every line, not just line 2).
        change = make_change(line=2, before="אבג", after="X", rationale="ambiguous with neighbours")
        proof_base = "אבג בלבד\nאבג אבג\nאבג לבדו\n"
        result, _, final_text, _ = self._run({"stage": "mechanical", "changes": [change]}, proof_base)
        out = result["changes"][0]
        self.assertFalse(out["applied"])
        self.assertEqual(out["skipReason"], "ambiguous-match")
        self.assertEqual(final_text, proof_base)


class TestOverlapMerge(ApplyChangesTestCase):
    def test_overlapping_edits_merge_one_applied_one_skipped(self):
        changes = [
            make_change(line=1, before="אבג", after="X", rationale="first"),
            make_change(line=1, before="גדה", after="Y", rationale="overlaps first"),
        ]
        proof_base = "אבגדה\n"
        result, _, final_text, _ = self._run({"stage": "mechanical", "changes": changes}, proof_base)
        applied = [c for c in result["changes"] if c["applied"]]
        skipped = [c for c in result["changes"] if not c["applied"]]
        self.assertEqual(len(applied), 1)
        self.assertEqual(len(skipped), 1)
        self.assertEqual(skipped[0]["skipReason"], "overlap")
        self.assertEqual(final_text, "Xדה\n")


